public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if (n < 0) { System.out.println("false"); return; }
        int orig = n, rev = 0;
        while (n > 0) { rev = rev * 10 + n % 10; n /= 10; }
        System.out.println(orig == rev ? "true" : "false");
    }
}

